const r = $input.first().json;
const fecha = String(r.fecha ?? 'hoy');
const ventas = Number(r.cierres ?? 0);
const facturas = Number(r.facturas ?? 0);
const gastos = Number(r.gastos ?? 0);
const pan = Number(r.control_pan ?? 0);
const mensaje = [
  `SIG La Maestra - Control del ${fecha}`,
  '',
  ventas > 0 ? 'Ventas diarias: registradas.' : 'Ventas diarias: falta ingresar el cierre.',
  pan > 0 ? 'Control de pan: registrado.' : 'Control de pan: sin registro para hoy.',
  `Facturas registradas hoy: ${facturas}.`,
  `Gastos operacionales registrados hoy: ${gastos}.`,
  '',
  'Comprueba si hubo facturas o gastos pendientes de ingresar.',
  'Que no existan facturas o gastos hoy no implica que falte un registro.'
].join('\n');
return [{ json: { fecha, mensaje } }];
